// Only public inventory, read-only. Do not infer live deployment from a repo pin.
const payload = $input.first()?.json || {};
const manifest = payload.body || payload;
if (!Array.isArray(manifest.categories) || !Array.isArray(manifest.osint_pinned_sources)) {
  return [{ json: { status: 'blocked_source_unavailable', valid: false, source: 'public GitHub category manifest' } }];
}
const expected = manifest.osint_pinned_sources.length;
const cases = manifest.categories.map(c => ({
  category: c.id, source_count: Number(c.repo_count || 0),
  source_covered: Number(c.repo_count || 0) >= 1,
  runtime_status: c.execution || 'unverified',
  remaining_validation: 'Actual tool/container n8n/Chief end-to-end execution receipt required'
}));
return [{
 json: {
  status: 'sources_indexed_not_deployed',
  checked_at: new Date().toISOString(),
  verified_screenshot_sets: manifest.original_uploaded_screenshots.map(x => ({count: x.count, files: x.filenames})),
  pinned_osint_refs: expected,
  categories: cases,
  prohibited_auto_actions: ['trade','publish','face identification','secrets','private image upload'],
  owner_action: 'Chief reviews real CI/provider endpoints; this read-only n8n manual check is not a deployment'
 }
}];
